<?php
declare(strict_types=1);
function catalog_filters(array $input): array { $allowed=['q','brand','category','gender','family','concentration','availability','season','occasion','intensity','tag','featured','new','promotion','sort'];$out=[];foreach($allowed as $key){$value=$input[$key]??null;if(is_array($value)||$value===null||$value==='')continue;if($key==='q')$value=trim(preg_replace('/\s+/u',' ',(string)$value)??'');if($key==='q')$value=mb_substr($value,0,100);if(in_array($key,['featured','new','promotion'],true)&&!in_array((string)$value,['0','1'],true))continue;$out[$key]=(string)$value;}return $out;}
function build_query_url(string $path,array $params=[]): string { $clean=[];foreach($params as $key=>$value)if($value!==null&&$value!==''&&!is_array($value))$clean[$key]=$value;return url($path).($clean?'?'.http_build_query($clean,'','&',PHP_QUERY_RFC3986):''); }
function catalog_label(string $type,string $value): string { $maps=['gender'=>['mujer'=>'Mujer','hombre'=>'Hombre','unisex'=>'Unisex','infantil'=>'Infantil','no_aplica'=>'No aplica'],'concentration'=>['parfum'=>'Parfum','extracto'=>'Extracto','eau_de_parfum'=>'Eau de Parfum','eau_de_toilette'=>'Eau de Toilette','eau_de_cologne'=>'Eau de Cologne','eau_fraiche'=>'Eau Fraîche','body_mist'=>'Body Mist','aceite'=>'Aceite','otro'=>'Otra presentación'],'availability'=>['disponible'=>'Disponible','pocas_unidades'=>'Pocas unidades','agotado'=>'Agotado','por_pedido'=>'Sobre pedido','pendiente'=>'Consultar disponibilidad','descontinuado'=>'Descontinuado']];return $maps[$type][$value]??ucwords(str_replace('_',' ',$value));}
function catalog_whatsapp(string $name,string $brand=''): string { return 'https://wa.me/'.preg_replace('/\D+/','',(string)Env::get('WHATSAPP_NUMBER','')).'?text='.rawurlencode("Hola, vi el perfume {$name}".($brand?" de {$brand}":'')." en la página de Les Sens. ¿Me podrían confirmar disponibilidad y presentaciones?"); }
